   ============================================================================ */
USE PharmacyManagementDB;
GO
IF EXISTS (SELECT 1 FROM dbo.Medicines)
BEGIN RAISERROR(N'Database đã có dữ liệu thuốc — dữ liệu mẫu chỉ chạy trên database vừa tạo bằng script v2.', 16, 1); SET NOEXEC ON; END
IF (SELECT COUNT(*) FROM dbo.Units WHERE (UnitCode='VIEN' AND UnitId=1) OR (UnitCode='VI' AND UnitId=2) OR (UnitCode='HOP' AND UnitId=3)
     OR (UnitCode='CHAI' AND UnitId=4) OR (UnitCode='LO' AND UnitId=5) OR (UnitCode='TUYP' AND UnitId=6) OR (UnitCode='GOI' AND UnitId=7)
     OR (UnitCode='ONG' AND UnitId=8) OR (UnitCode='ML' AND UnitId=9)) <> 9
   OR NOT EXISTS (SELECT 1 FROM dbo.Warehouses WHERE WarehouseId = 1 AND WarehouseCode = 'KHO01')
BEGIN RAISERROR(N'Seed của script v2 (Units, Warehouses) không đúng như kỳ vọng — hãy tạo lại database bằng script v2.', 16, 1); SET NOEXEC ON; END
GO
SET XACT_ABORT ON;
