(3, 17, 65, 2, N'Omeprazol có thể làm giảm hiệu quả của clopidogrel.', N'Cân nhắc thuốc thay thế; hỏi bác sĩ.'),
(4, 18, 65, 2, N'Esomeprazol có thể làm giảm hiệu quả của clopidogrel.', N'Cân nhắc thuốc thay thế; hỏi bác sĩ.'),
(5, 13, 53, 2, N'Calci làm giảm hấp thu ciprofloxacin.', N'Uống cách nhau ít nhất 2 giờ.'),
