(9, 4, 65, 2, N'Tăng nguy cơ chảy máu khi phối hợp.', N'Chỉ phối hợp theo chỉ định bác sĩ.'),
(10, 60, 61, 2, N'Phối hợp hai thuốc ức chế hệ renin–angiotensin làm tăng nguy cơ tăng kali máu, suy thận.', N'Hỏi bác sĩ trước khi dùng.'),
(11, 63, 96, 2, N'Fluconazol có thể làm tăng nồng độ atorvastatin.', N'Theo dõi đau cơ.'),
(12, 12, 91, 3, N'Clarithromycin làm tăng độc tính của colchicin.', N'Không phối hợp.'),
